import { PrimaryColumn } from 'typeorm';

/**
 * A UUIDv7 primary key generated by Postgres. Time-ordered, so it indexes
 * like a sequence, but safe to expose in URLs because it cannot be guessed
 * by counting.
 */
export const UuidPrimaryColumn = (constraintName: string): PropertyDecorator =>
  PrimaryColumn({
    type: 'uuid',
    default: () => 'uuidv7()',
    primaryKeyConstraintName: constraintName,
  });
